&lt;h1 id=&#34;web101&#34;&gt;&lt;a href=&#34;#web101&#34; class=&#34;headerlink&#34; title=&#34;web101&#34;&gt;&lt;/a&gt;web101&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-22 00:26:48
# @link: https://ctfer.com

*/

